Here is the commit message:
spi: ch341: fix memory leaks on probe failures

Make sure to deregister the controller, disable pins, and kill and free
the RX URB on probe failures to mirror disconnect and avoid memory
leaks and use-after-free.

Also add an explicit URB kill on disconnect for symmetry (even if that
is not strictly required as USB core would have stopped it in the
current setup).

Fixes: 8846739f52af ("spi: add ch341a usb2spi driver")
Cc: stable@vger.kernel.org	# 6.11
Cc: Johannes Thumshirn <jth@kernel.org>
Signed-off-by: Johan Hovold <johan@kernel.org>
Link: https://patch.msgid.link/20260327104305.1309915-2-johan@kernel.org
Signed-off-by: Mark Brown <broonie@kernel.org>

Here is the root cause:
Incomplete error handling in ch341_probe() leads to resource leaks (e.g., USB URB, pins, SPI controller) when subsequent allocation or configuration steps fail, because earlier successful steps are not undone. This results in memory leaks and potential use-after-free.

Here is the patch:

 static int ch341_probe(struct usb_interface *intf,
 		       const struct usb_device_id *id)
 {
 	struct usb_device *udev = interface_to_usbdev(intf);
 	struct usb_endpoint_descriptor *in, *out;
 	struct ch341_spi_dev *ch341;
 	struct spi_controller *ctrl;
 	int ret;

 	ret = usb_find_common_endpoints(intf->cur_altsetting, &in, &out, NULL,
 					NULL);
 	if (ret)
 		return ret;

 	ctrl = devm_spi_alloc_host(&udev->dev, sizeof(struct ch341_spi_dev));
 	if (!ctrl)
 		return -ENOMEM;

 	ch341 = spi_controller_get_devdata(ctrl);
 	ch341->ctrl = ctrl;
 	ch341->udev = udev;
 	ch341->write_pipe = usb_sndbulkpipe(udev, usb_endpoint_num(out));
 	ch341->read_pipe = usb_rcvbulkpipe(udev, usb_endpoint_num(in));

 	ch341->rx_len = usb_endpoint_maxp(in);
 	ch341->rx_buf = devm_kzalloc(&udev->dev, ch341->rx_len, GFP_KERNEL);
 	if (!ch341->rx_buf)
 		return -ENOMEM;

 	ch341->rx_urb = usb_alloc_urb(0, GFP_KERNEL);
 	if (!ch341->rx_urb)
 		return -ENOMEM;

 	ch341->tx_buf =
 		devm_kzalloc(&udev->dev, CH341_PACKET_LENGTH, GFP_KERNEL);
-	if (!ch341->tx_buf)
-		return -ENOMEM;
+	if (!ch341->tx_buf) {
+		ret = -ENOMEM;
+		goto err_free_urb;
+	}

 	usb_fill_bulk_urb(ch341->rx_urb, udev, ch341->read_pipe, ch341->rx_buf,
 			  ch341->rx_len, ch341_recv, ch341);

 	ret = usb_submit_urb(ch341->rx_urb, GFP_KERNEL);
-	if (ret) {
-		usb_free_urb(ch341->rx_urb);
-		return -ENOMEM;
-	}
+	if (ret)
+		goto err_free_urb;

 	ctrl->bus_num = -1;
 	ctrl->mode_bits = SPI_CPHA;
 	ctrl->transfer_one = ch341_transfer_one;
 	ctrl->set_cs = ch341_set_cs;
 	ctrl->auto_runtime_pm = false;

 	usb_set_intfdata(intf, ch341);

 	ret = ch341_config_stream(ch341);
 	if (ret)
-		return ret;
+		goto err_kill_urb;

 	ret = ch341_enable_pins(ch341, true);
 	if (ret)
-		return ret;
+		goto err_kill_urb;

 	ret = spi_register_controller(ctrl);
 	if (ret)
-		return ret;
+		goto err_disable_pins;

 	ch341->spidev = spi_new_device(ctrl, &chip);
-	if (!ch341->spidev)
-		return -ENOMEM;
+	if (!ch341->spidev) {
+		ret = -ENOMEM;
+		goto err_unregister;
+	}

 	return 0;
+
+err_unregister:
+	spi_unregister_controller(ctrl);
+err_disable_pins:
+	ch341_enable_pins(ch341, false);
+err_kill_urb:
+	usb_kill_urb(ch341->rx_urb);
+err_free_urb:
+	usb_free_urb(ch341->rx_urb);
+
+	return ret;
 }

 static void ch341_disconnect(struct usb_interface *intf)
 {
 	struct ch341_spi_dev *ch341 = usb_get_intfdata(intf);

 	spi_unregister_device(ch341->spidev);
 	spi_unregister_controller(ch341->ctrl);
 	ch341_enable_pins(ch341, false);
+	usb_kill_urb(ch341->rx_urb);
 	usb_free_urb(ch341->rx_urb);
 }



